function(container, apiUrl, tables) {
  const statusFilterEl = container.querySelector('[data-testid="status-filter"]');
  const searchBtnEl = container.querySelector('[data-testid="search-button"]');
  const exportBtnEl = container.querySelector('[data-testid="export-csv-button"]');
  const tbodyEl = container.querySelector('#applications-tbody');
  const emptyStateEl = container.querySelector('#empty-state');

  const detailModalEl = container.querySelector('#detail-modal');
  const closeModalBtnEl = container.querySelector('#close-modal-btn');
  const approveButtonEl = container.querySelector('#approve-button');
  const rejectButtonEl = container.querySelector('#reject-button');
  const holdButtonEl = container.querySelector('#hold-button');
  const rejectionReasonEl = container.querySelector('#rejection-reason');
  const rejectionSectionEl = container.querySelector('#rejection-section');

  const confirmDialogEl = container.querySelector('#confirm-dialog');
  const confirmCancelBtnEl = container.querySelector('#confirm-cancel-btn');
  const confirmOkBtnEl = container.querySelector('#confirm-ok-btn');
  const confirmTitleEl = container.querySelector('#confirm-title');
  const confirmMessageEl = container.querySelector('#confirm-message');

  let currentApplicationId = null;
  let pendingAction = null;

  // Fetch and render applications list
  async function loadApplications() {
    const applications = await window.aivicApi.list(0); // Table index 0: 予約申込
    if (!applications) return;

    const statusFilter = statusFilterEl.value;
    const filtered = statusFilter ? applications.filter(app => app.予約状態 === statusFilter) : applications;

    if (filtered.length === 0) {
      tbodyEl.innerHTML = '';
      emptyStateEl.style.display = 'block';
      return;
    }

    emptyStateEl.style.display = 'none';
    tbodyEl.innerHTML = filtered.map(app => {
      const approvalStatus = getApprovalStatus(app);
      const statusBadge = getStatusBadge(app.予約状態);
      const reservationDateTime = formatDateTime(app.利用開始日時);

      return `
        <tr data-id="${app.予約申込ID}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 200ms;">
          <td style="padding: 10px 8px; border-right: 1px solid var(--border);">${escapeHtml(app.団体名 || '-')}</td>
          <td style="padding: 10px 8px; border-right: 1px solid var(--border);">${escapeHtml(app.利用者名 || '-')}</td>
          <td style="padding: 10px 8px; border-right: 1px solid var(--border);">${reservationDateTime}</td>
          <td style="padding: 10px 8px; border-right: 1px solid var(--border);">${escapeHtml(app.施設名 || '-')}</td>
          <td style="padding: 10px 8px; text-align: center; border-right: 1px solid var(--border);">${app.利用人数 || '-'}</td>
          <td style="padding: 10px 8px; border-right: 1px solid var(--border);">
            <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: ${approvalStatus.bgColor}; color: ${approvalStatus.textColor};">
              ${approvalStatus.label}
            </span>
          </td>
          <td style="padding: 10px 8px; border-right: 1px solid var(--border);">${statusBadge}</td>
          <td style="padding: 10px 8px; text-align: center;">
            <button class="action-row-btn" data-id="${app.予約申込ID}" style="padding: 4px 8px; background: var(--primary); color: #fff; border: none; border-radius: 3px; font-size: 12px; cursor: pointer; font-weight: 500;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    // Attach row click handlers
    tbodyEl.querySelectorAll('.action-row-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const appId = btn.dataset.id;
        openDetailModal(appId, filtered);
      });
    });
  }

  function getApprovalStatus(app) {
    // Simulate approval criteria judgment
    // In real scenario, this would be based on 予約承認基準 table
    const numPeople = app.利用人数 || 0;
    const isGroup = !!app.団体ID;

    if (numPeople > 100 || (isGroup && numPeople > 50)) {
      return { label: '要確認', bgColor: '#f59e0b', textColor: '#fff' };
    } else if (numPeople > 0) {
      return { label: '自動承認可', bgColor: '#10b981', textColor: '#fff' };
    }
    return { label: '判定待機', bgColor: 'var(--border)', textColor: 'var(--text)' };
  }

  function getStatusBadge(status) {
    const statusMap = {
      '新規受付': '<span style="display: inline-block; padding: 4px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: #3b82f6; color: #fff;">新規受付</span>',
      '承認済': '<span style="display: inline-block; padding: 4px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: #10b981; color: #fff;">承認済</span>',
      '却下': '<span style="display: inline-block; padding: 4px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: #ef4444; color: #fff;">却下</span>',
      '保留': '<span style="display: inline-block; padding: 4px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: #f59e0b; color: #fff;">保留</span>'
    };
    return statusMap[status] || '-';
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP') + ' ' + date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  function openDetailModal(appId, applications) {
    const app = applications.find(a => a.予約申込ID === appId);
    if (!app) return;

    currentApplicationId = appId;
    pendingAction = null;

    // Populate detail info
    container.querySelector('#detail-group-name').textContent = app.団体名 || '-';
    container.querySelector('#detail-user-name').textContent = app.利用者名 || '-';
    container.querySelector('#detail-reservation-date').textContent = formatDateTime(app.利用開始日時);
    container.querySelector('#detail-num-people').textContent = app.利用人数 || '-';

    const approvalStatus = getApprovalStatus(app);
    container.querySelector('#detail-approval-result').innerHTML = 
      `<span style="display: inline-block; padding: 4px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: ${approvalStatus.bgColor}; color: ${approvalStatus.textColor};">${approvalStatus.label}</span>`;

    // Reset rejection reason
    rejectionReasonEl.value = '';
    rejectionSectionEl.style.display = 'none';

    // Show modal
    detailModalEl.style.display = 'flex';
  }

  function closeDetailModal() {
    detailModalEl.style.display = 'none';
    currentApplicationId = null;
    pendingAction = null;
  }

  function closeConfirmDialog() {
    confirmDialogEl.style.display = 'none';
  }

  // Event listeners
  searchBtnEl.addEventListener('click', loadApplications);
  statusFilterEl.addEventListener('change', loadApplications);

  closeModalBtnEl.addEventListener('click', closeDetailModal);
  detailModalEl.addEventListener('click', (e) => {
    if (e.target === detailModalEl) closeDetailModal();
  });

  confirmCancelBtnEl.addEventListener('click', closeConfirmDialog);
  confirmDialogEl.addEventListener('click', (e) => {
    if (e.target === confirmDialogEl) closeConfirmDialog();
  });

  approveButtonEl.addEventListener('click', () => {
    pendingAction = 'approve';
    confirmTitleEl.textContent = '承認確認';
    confirmMessageEl.textContent = 'この予約申込を承認してもよろしいですか？';
    confirmDialogEl.style.display = 'flex';
  });

  rejectButtonEl.addEventListener('click', () => {
    rejectionSectionEl.style.display = 'block';
    pendingAction = 'reject';
    confirmTitleEl.textContent = '却下確認';
    confirmMessageEl.textContent = '却下理由を入力してください。';
    // Don't show confirm dialog yet; wait for reason input
  });

  holdButtonEl.addEventListener('click', () => {
    pendingAction = 'hold';
    confirmTitleEl.textContent = '保留確認';
    confirmMessageEl.textContent = 'この予約申込を保留にしてもよろしいですか？';
    confirmDialogEl.style.display = 'flex';
  });

  confirmOkBtnEl.addEventListener('click', async () => {
    if (pendingAction === 'reject') {
      const reason = rejectionReasonEl.value.trim();
      if (!reason) {
        alert('却下理由を入力してください');
        return;
      }
      await executeAction('却下', reason);
    } else if (pendingAction === 'approve') {
      await executeAction('承認済');
    } else if (pendingAction === 'hold') {
      await executeAction('保留');
    }
    closeConfirmDialog();
    closeDetailModal();
    loadApplications();
  });

  async function executeAction(newStatus, reason = null) {
    const updated = await window.aivicApi.update(0, currentApplicationId, {
      予約状態: newStatus,
      備考: reason || ''
    });
    if (updated) {
      // Log the action
      await window.aivicApi.save(8, { // Table index 8: 代行予約ログ
        施設管理者ID: 'current-admin-id',
        利用者ID: 'current-user-id',
        予約申込ID: currentApplicationId,
        操作種別: newStatus === '承認済' ? '承認' : newStatus === '却下' ? '却下' : '保留',
        操作内容: reason || '',
        代行理由: '',
        操作日時: new Date().toISOString()
      });
    }
  }

  exportBtnEl.addEventListener('click', async () => {
    const applications = await window.aivicApi.list(0);
    if (!applications || applications.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['団体名', '利用者名', '予約日時', '施設名', '利用人数', '承認基準判定', '受付状況'];
    const rows = applications.map(app => {
      const approvalStatus = getApprovalStatus(app);
      return [
        app.団体名 || '',
        app.利用者名 || '',
        formatDateTime(app.利用開始日時),
        app.施設名 || '',
        app.利用人数 || '',
        approvalStatus.label,
        app.予約状態 || ''
      ];
    });

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => {
        const str = String(cell);
        return str.includes(',') || str.includes('"') || str.includes('\n') 
          ? `"${str.replace(/"/g, '""')}"` 
          : str;
      }).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予約申込_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // Initial load
  loadApplications();
}

function(container, apiUrl, tables) {
  const orgFilterEl = container.querySelector('[data-testid="organization-filter"]');
  const periodStartEl = container.querySelector('[data-testid="period-start"]');
  const periodEndEl = container.querySelector('[data-testid="period-end"]');
  const calculateBtnEl = container.querySelector('[data-testid="calculate-button"]');
  const exportBtnEl = container.querySelector('[data-testid="export-csv-button"]');
  const calcTbodyEl = container.querySelector('#calculation-tbody');
  const collectionTbodyEl = container.querySelector('#collection-tbody');
  const modalEl = container.querySelector('#calculation-modal');

  // Summary card elements
  const summaryBillingEl = container.querySelector('#summary-billing');
  const summaryCollectedEl = container.querySelector('#summary-collected');
  const summaryOutstandingEl = container.querySelector('#summary-outstanding');
  const summaryRefundEl = container.querySelector('#summary-refund');

  // State
  let calculationResults = [];
  let collectionStatuses = [];

  // Initialize date inputs with default range (current month)
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);
  periodStartEl.value = firstDay.toISOString().split('T')[0];
  periodEndEl.value = lastDay.toISOString().split('T')[0];

  // Format currency
  function formatCurrency(amount) {
    return '¥' + amount.toLocaleString('ja-JP');
  }

  // Format date
  function formatDate(dateStr) {
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit' });
  }

  // Render calculation results table
  function renderCalculationResults() {
    if (calculationResults.length === 0) {
      calcTbodyEl.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="6" style="padding: 24px 12px; text-align: center; color: var(--text-muted); font-size: 12px;">計算実行後に結果が表示されます</td></tr>';
      return;
    }

    calcTbodyEl.innerHTML = calculationResults.map((row, idx) => `
      <tr style="border-bottom: 1px solid var(--border); ${idx % 2 === 0 ? '' : 'background: rgba(255,255,255,0.02);'}">
        <td style="padding: 10px 12px; border-right: 1px solid var(--border);">${row.userName || '—'}</td>
        <td style="padding: 10px 12px; border-right: 1px solid var(--border);">${row.usageDateTime || '—'}</td>
        <td style="padding: 10px 12px; text-align: right; border-right: 1px solid var(--border);">${formatCurrency(row.baseFee || 0)}</td>
        <td style="padding: 10px 12px; text-align: right; border-right: 1px solid var(--border);">${formatCurrency(row.discountAmount || 0)}</td>
        <td style="padding: 10px 12px; text-align: right; border-right: 1px solid var(--border);">${formatCurrency(row.tax || 0)}</td>
        <td style="padding: 10px 12px; text-align: right; font-weight: 600;">${formatCurrency(row.totalFee || 0)}</td>
      </tr>
    `).join('');
  }

  // Render collection status table
  function renderCollectionStatus() {
    if (collectionStatuses.length === 0) {
      collectionTbodyEl.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 24px 12px; text-align: center; color: var(--text-muted); font-size: 12px;">計算実行後に結果が表示されます</td></tr>';
      return;
    }

    collectionTbodyEl.innerHTML = collectionStatuses.map((row, idx) => {
      let statusBadge = '未収納';
      let statusColor = 'var(--text-muted)';
      if (row.status === 'collected') {
        statusBadge = '全額収納';
        statusColor = '#10b981';
      } else if (row.status === 'partial') {
        statusBadge = '部分収納';
        statusColor = '#f59e0b';
      } else if (row.status === 'refunded') {
        statusBadge = '返金完了';
        statusColor = '#8b5cf6';
      }

      return `
        <tr style="border-bottom: 1px solid var(--border); ${idx % 2 === 0 ? '' : 'background: rgba(255,255,255,0.02);'}">
          <td style="padding: 10px 12px; border-right: 1px solid var(--border);">${row.userName || '—'}</td>
          <td style="padding: 10px 12px; text-align: right; border-right: 1px solid var(--border);">${formatCurrency(row.billingAmount || 0)}</td>
          <td style="padding: 10px 12px; text-align: right; border-right: 1px solid var(--border);">${formatCurrency(row.collectedAmount || 0)}</td>
          <td style="padding: 10px 12px; text-align: right; border-right: 1px solid var(--border);">${formatCurrency(row.outstandingAmount || 0)}</td>
          <td style="padding: 10px 12px; text-align: center;">
            <span style="display: inline-block; padding: 4px 8px; background: rgba(255,255,255,0.08); color: ${statusColor}; border-radius: 3px; font-size: 12px; font-weight: 500;">${statusBadge}</span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // Update summary cards
  function updateSummary() {
    let totalBilling = 0;
    let totalCollected = 0;
    let totalOutstanding = 0;
    let totalRefund = 0;

    collectionStatuses.forEach(row => {
      totalBilling += row.billingAmount || 0;
      totalCollected += row.collectedAmount || 0;
      totalOutstanding += row.outstandingAmount || 0;
      totalRefund += row.refundAmount || 0;
    });

    summaryBillingEl.textContent = formatCurrency(totalBilling);
    summaryCollectedEl.textContent = formatCurrency(totalCollected);
    summaryOutstandingEl.textContent = formatCurrency(totalOutstanding);
    summaryRefundEl.textContent = formatCurrency(totalRefund);
  }

  // Show modal
  function showModal() {
    modalEl.style.display = 'flex';
  }

  // Hide modal
  function hideModal() {
    modalEl.style.display = 'none';
  }

  // Calculate button click handler
  calculateBtnEl.addEventListener('click', async () => {
    const orgId = orgFilterEl.value || null;
    const startDate = periodStartEl.value;
    const endDate = periodEndEl.value;

    if (!startDate || !endDate) {
      alert('開始日と終了日を指定してください');
      return;
    }

    showModal();

    try {
      // Simulate calculation delay
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Fetch reservation data (table index 4: 予約申込)
      const reservations = await window.aivicApi.list(4);
      if (!reservations) {
        hideModal();
        alert('予約データの取得に失敗しました');
        return;
      }

      // Fetch collection status data (table index 11: 収納状況)
      const collections = await window.aivicApi.list(11);
      if (!collections) {
        hideModal();
        alert('収納状況データの取得に失敗しました');
        return;
      }

      // Filter by organization and date range
      const filtered = reservations.filter(r => {
        const rStart = new Date(r.利用開始日時);
        const filterStart = new Date(startDate);
        const filterEnd = new Date(endDate);
        const dateMatch = rStart >= filterStart && rStart <= filterEnd;
        const orgMatch = !orgId || r.団体ID === orgId;
        return dateMatch && orgMatch;
      });

      // Build calculation results
      calculationResults = filtered.map(r => ({
        userName: r.利用者ID || '—',
        usageDateTime: r.利用開始日時 ? formatDate(r.利用開始日時) : '—',
        baseFee: r.料金 || 0,
        discountAmount: Math.floor((r.料金 || 0) * 0.1), // Simulated 10% discount
        tax: Math.floor((r.料金 || 0) * 0.1 * 0.1), // Simulated 10% tax
        totalFee: Math.floor((r.料金 || 0) * 0.9 * 1.1), // After discount and tax
      }));

      // Build collection status
      collectionStatuses = filtered.map(r => {
        const billing = Math.floor((r.料金 || 0) * 0.9 * 1.1);
        const collected = Math.floor(billing * 0.7); // Simulated 70% collected
        const outstanding = billing - collected;
        const status = collected === 0 ? 'uncollected' : (collected === billing ? 'collected' : 'partial');

        return {
          userName: r.利用者ID || '—',
          billingAmount: billing,
          collectedAmount: collected,
          outstandingAmount: outstanding,
          refundAmount: 0,
          status: status,
        };
      });

      renderCalculationResults();
      renderCollectionStatus();
      updateSummary();

      hideModal();
    } catch (error) {
      hideModal();
      console.error('Calculation error:', error);
      alert('料金計算中にエラーが発生しました');
    }
  });

  // CSV Export button click handler
  exportBtnEl.addEventListener('click', () => {
    if (calculationResults.length === 0) {
      alert('エクスポートするデータがありません。先に料金計算を実行してください。');
      return;
    }

    const headers = ['利用者', '利用日時', '基本料金', '割引額', '税金', '合計料金'];
    const rows = calculationResults.map(r => [
      r.userName,
      r.usageDateTime,
      r.baseFee,
      r.discountAmount,
      r.tax,
      r.totalFee,
    ]);

    // Build CSV
    const csv = [
      '\uFEFF' + headers.join(','),
      ...rows.map(row => row.map(cell => {
        const str = String(cell);
        return str.includes(',') || str.includes('"') ? `"${str.replace(/"/g, '""')}"` : str;
      }).join(',')),
    ].join('\n');

    // Download
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `料金計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // Close modal on backdrop click
  modalEl.addEventListener('click', (e) => {
    if (e.target === modalEl) {
      hideModal();
    }
  });

  // Close modal on Escape key
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modalEl.style.display !== 'none') {
      hideModal();
    }
  });
}

function(container, apiUrl, tables) {
  const reportTypeSelect = container.querySelector('[data-testid="report-type-select"]');
  const startDateInput = container.querySelector('[data-testid="start-date-input"]');
  const endDateInput = container.querySelector('[data-testid="end-date-input"]');
  const groupFilterSelect = container.querySelector('[data-testid="group-filter-select"]');
  const previewButton = container.querySelector('[data-testid="preview-button"]');
  const downloadButton = container.querySelector('[data-testid="download-button"]');
  const previewArea = container.querySelector('#preview-area');
  const historyTbody = container.querySelector('#history-tbody');
  const downloadModal = container.querySelector('#download-modal');
  const confirmDownloadButton = container.querySelector('[data-testid="confirm-download-button"]');
  const cancelDownloadButton = container.querySelector('[data-testid="cancel-download-button"]');
  const downloadConfirmText = container.querySelector('#download-confirm-text');

  let currentPreviewData = null;
  let currentReportType = null;
  let currentOutputFormat = 'csv';

  // Initialize groups dropdown
  async function loadGroups() {
    try {
      const groups = await window.aivicApi.list(3); // 団体テーブル
      if (groups && groups.length > 0) {
        const groupOptions = groups.map(g => `<option value="${g.id}">${g.団体名}</option>`).join('');
        groupFilterSelect.innerHTML = '<option value="">全団体</option>' + groupOptions;
      }
    } catch (e) {
      console.error('Failed to load groups:', e);
    }
  }

  // Load operation history
  async function loadHistory() {
    try {
      const history = await window.aivicApi.list(1); // 操作履歴テーブル
      if (history && history.length > 0) {
        const rows = history
          .filter(h => h.操作種別 === 'ダウンロード' || h.操作種別 === '帳票出力')
          .sort((a, b) => new Date(b.実行開始日時) - new Date(a.実行開始日時))
          .slice(0, 20);

        historyTbody.innerHTML = rows.map(row => {
          const date = new Date(row.実行開始日時).toLocaleString('ja-JP');
          return `<tr style="border-bottom: 1px solid var(--border);">
            <td style="padding: 8px 6px; color: var(--text); font-size: 11px; word-break: break-word;">${date}</td>
          </tr>`;
        }).join('');
      }
    } catch (e) {
      console.error('Failed to load history:', e);
      historyTbody.innerHTML = '<tr><td style="padding: 8px 6px; color: var(--text-muted);">履歴の読込に失敗しました</td></tr>';
    }
  }

  // Generate preview data based on report type
  async function generatePreview() {
    const reportType = reportTypeSelect.value;
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const groupId = groupFilterSelect.value;

    if (!reportType) {
      previewArea.innerHTML = '<div style="color: var(--text-muted);">帳票種別を選択してください</div>';
      return;
    }

    if (!startDate || !endDate) {
      previewArea.innerHTML = '<div style="color: var(--text-muted);">期間を指定してください</div>';
      return;
    }

    try {
      let data = [];
      let headers = [];

      if (reportType === 'reservations') {
        // 予約一覧
        data = await window.aivicApi.list(4); // 予約申込テーブル
        headers = ['予約ID', '利用者名', '利用開始日時', '利用終了日時', '利用人数', '料金', '予約状態', '支払状態'];
        data = data.filter(r => {
          const rDate = new Date(r.利用開始日時);
          return rDate >= new Date(startDate) && rDate <= new Date(endDate);
        });
        if (groupId) {
          data = data.filter(r => r.団体ID === groupId);
        }
      } else if (reportType === 'usage') {
        // 利用実績
        data = await window.aivicApi.list(11); // 利用実績テーブル
        headers = ['利用実績ID', '利用者名', '利用開始日時', '利用終了日時', '利用時間分', '利用人数', '実績ステータス'];
        data = data.filter(r => {
          const rDate = new Date(r.利用開始日時);
          return rDate >= new Date(startDate) && rDate <= new Date(endDate);
        });
        if (groupId) {
          data = data.filter(r => r.団体ID === groupId);
        }
      } else if (reportType === 'billing') {
        // 料金計算結果
        data = await window.aivicApi.list(9); // 利用料金計算結果テーブル
        headers = ['計算結果ID', '利用者名', '基本料金', '割引額', '割引率', '税金', '合計料金', '計算ステータス'];
        data = data.filter(r => {
          const rDate = new Date(r.計算日時);
          return rDate >= new Date(startDate) && rDate <= new Date(endDate);
        });
      } else if (reportType === 'collection') {
        // 収納状況
        data = await window.aivicApi.list(10); // 収納状況テーブル
        headers = ['収納ID', '請求金額', '収納済金額', '未収金額', '返金予定金額', '返金済金額', '収納状況ステータス'];
      }

      currentPreviewData = { headers, data, reportType };
      currentReportType = reportType;

      // Render preview table
      const tableHtml = `
        <table style="width: 100%; border-collapse: collapse; font-size: 12px;">
          <thead>
            <tr style="border-bottom: 1px solid var(--border); background: var(--bg-main);">
              ${headers.map(h => `<th style="text-align: left; padding: 8px 6px; color: var(--text); font-weight: 600;">${h}</th>`).join('')}
            </tr>
          </thead>
          <tbody>
            ${data.slice(0, 10).map(row => `
              <tr style="border-bottom: 1px solid var(--border);">
                ${headers.map(h => {
                  const val = row[h] || '';
                  const displayVal = typeof val === 'number' ? val.toLocaleString('ja-JP') : String(val).substring(0, 30);
                  return `<td style="padding: 8px 6px; color: var(--text);">${displayVal}</td>`;
                }).join('')}
              </tr>
            `).join('')}
          </tbody>
        </table>
        <div style="margin-top: 12px; font-size: 12px; color: var(--text-muted);">
          全 ${data.length} 件中、最初の 10 件を表示
        </div>
      `;
      previewArea.innerHTML = tableHtml;
    } catch (e) {
      console.error('Failed to generate preview:', e);
      previewArea.innerHTML = '<div style="color: var(--text-muted);">プレビューの生成に失敗しました</div>';
    }
  }

  // Download handler
  function handleDownload() {
    if (!currentPreviewData) {
      previewArea.innerHTML = '<div style="color: var(--text-muted);">先にプレビューボタンをクリックしてください</div>';
      return;
    }

    const format = document.querySelector('input[name="output-format"]:checked').value;
    currentOutputFormat = format;

    const reportTypeLabel = {
      'reservations': '予約一覧',
      'usage': '利用実績',
      'billing': '料金計算結果',
      'collection': '収納状況'
    }[currentReportType] || '帳票';

    downloadConfirmText.textContent = `${reportTypeLabel}を${format.toUpperCase()}形式でダウンロードします。よろしいですか？`;
    downloadModal.style.display = 'flex';
  }

  // Confirm download
  async function confirmDownload() {
    const { headers, data } = currentPreviewData;
    const format = currentOutputFormat;

    try {
      if (format === 'csv') {
        downloadAsCSV(headers, data);
      } else if (format === 'excel') {
        downloadAsExcel(headers, data);
      } else if (format === 'pdf') {
        downloadAsPDF(headers, data);
      }

      // Record operation history
      await window.aivicApi.save(1, {
        操作種別: 'ダウンロード',
        対象リソースタイプ: '帳票',
        対象リソースID: currentReportType,
        操作内容: `${currentReportType}を${format}形式でダウンロード`,
        操作ステータス: '成功',
        実行開始日時: new Date().toISOString(),
        実行終了日時: new Date().toISOString()
      });

      downloadModal.style.display = 'none';
      loadHistory();
    } catch (e) {
      console.error('Download failed:', e);
      alert('ダウンロードに失敗しました');
    }
  }

  // CSV download
  function downloadAsCSV(headers, data) {
    const BOM = '\uFEFF';
    const csvContent = [
      headers.join(','),
      ...data.map(row => headers.map(h => {
        const val = row[h] || '';
        const str = String(val).replace(/"/g, '""');
        return str.includes(',') || str.includes('"') || str.includes('\n') ? `"${str}"` : str;
      }).join(','))
    ].join('\n');

    const blob = new Blob([BOM + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `report_${currentReportType}_${new Date().getTime()}.csv`;
    link.click();
  }

  // Excel download (simplified CSV-like format)
  function downloadAsExcel(headers, data) {
    downloadAsCSV(headers, data); // For simplicity, use CSV format
  }

  // PDF download (simplified text format)
  function downloadAsPDF(headers, data) {
    const content = [
      headers.join('\t'),
      ...data.map(row => headers.map(h => row[h] || '').join('\t'))
    ].join('\n');

    const blob = new Blob([content], { type: 'text/plain;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `report_${currentReportType}_${new Date().getTime()}.txt`;
    link.click();
  }

  // Event listeners
  previewButton.addEventListener('click', generatePreview);
  downloadButton.addEventListener('click', handleDownload);
  confirmDownloadButton.addEventListener('click', confirmDownload);
  cancelDownloadButton.addEventListener('click', () => {
    downloadModal.style.display = 'none';
  });

  // Close modal on overlay click
  downloadModal.addEventListener('click', (e) => {
    if (e.target === downloadModal) {
      downloadModal.style.display = 'none';
    }
  });

  // Close modal on Escape key
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && downloadModal.style.display !== 'none') {
      downloadModal.style.display = 'none';
    }
  });

  // Initialize
  loadGroups();
  loadHistory();
}
